// Bit-exact parity test for the QSA indexer primitive (cpp/engine/src/qsa.cpp)
// vs vectors generated by the real Python op path (tools/gen_qsa_vectors.py).
// Compares raw bytes (uint32 view), not tolerances.
//
// Standalone build (no CMake edits required):
//   MLXROOT=.venv/lib/python3.12/site-packages/mlx
//   xcrun clang++ -std=c++20 -O2 -I"$MLXROOT/include" -Icpp/engine/src \
//       cpp/engine/src/qsa.cpp cpp/engine/tests/test_qsa.cpp \
//       -L"$MLXROOT/lib" -lmlx -Wl,-rpath,"$(pwd)/$MLXROOT/lib" -o /tmp/test_qsa
//   /tmp/test_qsa cpp/engine/tests/vectors_qsa
#include "qsa.hpp"

#include <mlx/mlx.h>

#include <cstdint>
#include <cstdio>
#include <fstream>
#include <string>
#include <vector>

namespace mx = mlx::core;
using namespace veystrix::engine;

static bool bit_equal(const mx::array& a, const mx::array& b) {
  if (a.shape() != b.shape()) return false;
  mx::array av = mx::astype(mx::reshape(a, {-1}), mx::uint32);
  mx::array bv = mx::astype(mx::reshape(b, {-1}), mx::uint32);
  mx::eval(av, bv);
  if (av.size() != bv.size()) return false;
  const uint32_t* pa = av.data<uint32_t>();
  const uint32_t* pb = bv.data<uint32_t>();
  for (size_t i = 0; i < av.size(); ++i)
    if (pa[i] != pb[i]) return false;
  return true;
}

static double get_num(const std::string& s, const std::string& key) {
  auto pos = s.find("\"" + key + "\"");
  if (pos == std::string::npos) return 0.0;
  auto colon = s.find(':', pos);
  size_t i = colon + 1;
  while (i < s.size() && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n')) ++i;
  std::string num;
  for (; i < s.size(); ++i) {
    char c = s[i];
    if (c == ',' || c == '\n' || c == '}' || c == ' ' || c == '\t') break;
    num += c;
  }
  return std::stod(num);
}

static int run_case(const std::string& root, const std::string& name) {
  std::string dir = root + "/" + name;
  auto load = [&](const char* n) { return mx::load(dir + "/" + n + ".npy"); };
  std::ifstream mf(dir + "/meta.json");
  std::string meta((std::istreambuf_iterator<char>(mf)),
                   std::istreambuf_iterator<char>());

  QSAConfig cfg;
  cfg.n_heads = static_cast<int>(get_num(meta, "n_heads"));
  cfg.kv_heads = static_cast<int>(get_num(meta, "kv_heads"));
  cfg.head_dim = static_cast<int>(get_num(meta, "head_dim"));
  cfg.compress_ratio = static_cast<int>(get_num(meta, "compress_ratio"));
  cfg.token_budget = static_cast<int>(get_num(meta, "token_budget"));
  cfg.block_topk = static_cast<int>(get_num(meta, "block_topk"));
  cfg.eps = static_cast<float>(get_num(meta, "eps"));

  mx::array x = load("x"), pw = load("proj_weight");
  mx::array qw = load("q_weight"), kw = load("k_weight");
  mx::array exp_query = load("query"), exp_pooled = load("pooled_keys");

  QSAIndexerOutput out = qsa_indexer_pre_rope(x, pw, qw, kw, cfg);
  mx::eval(out.query, out.pooled_keys);

  if (!bit_equal(out.query, exp_query)) {
    std::fprintf(stderr, "[%s] query differs\n", name.c_str());
    return 1;
  }
  if (!bit_equal(out.pooled_keys, exp_pooled)) {
    std::fprintf(stderr, "[%s] pooled_keys differs\n", name.c_str());
    return 1;
  }
  std::printf("  [%s] OK (query + pooled_keys bit-identical)\n", name.c_str());
  return 0;
}

int main(int argc, char** argv) {
  std::string root = argc > 1 ? argv[1] : "cpp/engine/tests/vectors_qsa";
  std::ifstream f(root + "/cases.json");
  if (!f) {
    std::fprintf(stderr, "cases.json missing; run gen_qsa_vectors.py\n");
    return 2;
  }
  std::string text((std::istreambuf_iterator<char>(f)),
                   std::istreambuf_iterator<char>());
  std::vector<std::string> cases;
  size_t pos = 0;
  while ((pos = text.find("\"dir\"", pos)) != std::string::npos) {
    auto q1 = text.find('"', text.find(':', pos) + 1);
    auto q2 = text.find('"', q1 + 1);
    if (q1 != std::string::npos && q2 != std::string::npos)
      cases.push_back(text.substr(q1 + 1, q2 - q1 - 1));
    pos = q2;
  }
  if (cases.empty()) {
    std::fprintf(stderr, "no cases parsed\n");
    return 2;
  }
  int failed = 0;
  for (const auto& c : cases) failed += run_case(root, c);
  if (failed) {
    std::fprintf(stderr, "%d QSA case(s) FAILED\n", failed);
    return 1;
  }
  std::printf("test_qsa OK (%zu cases bit-identical to Python)\n", cases.size());
  return 0;
}
